{
  "county_id": "HVA90",
  "actions": [
    {
      "action_id": "screening-reminders",
      "action": "Send a second kit with plain-language, multilingual instructions to non-responders; measure the gain as a stepped pilot.",
      "rationale": "City of Helsinki colorectal screening participation is 70.8% against the 80% target, and the portfolio assigns screening-reminders to this county with an assumed cost of 277757 euros per year.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of invited to colorectal cancer screening who attended, %",
      "roadmap_measure": "1.3.1"
    },
    {
      "action_id": "self-sampling",
      "action": "Mail a self-sampling kit with the second reminder to everyone who has not attended.",
      "rationale": "City of Helsinki cervical screening participation is 71% against the 80% target, and the portfolio assigns self-sampling to this county with an assumed cost of 416635 euros per year.",
      "owner_role": "Wellbeing services county screening unit",
      "indicator": "Proportion of women invited to cervical cancer screening (smear test) who attended, %",
      "roadmap_measure": "2.4.4"
    },
    {
      "action_id": "pathway-timestamps",
      "action": "Add first contact, referral, diagnosis and first treatment dates, plus entry route, to the national cancer quality register and publish county-level medians quarterly.",
      "rationale": "This is the first step for every county, and City of Helsinki cannot check the Goal 3 indicator treatment within target times from open data because time from referral to diagnosis and from diagnosis to first treatment is not published by county for any cancer.",
      "owner_role": "FICAN with THL and the Finnish Cancer Registry",
      "indicator": "Share of new cancer cases with all four timestamps recorded",
      "roadmap_measure": "3.2.1"
    }
  ],
  "evidence_does_not_support": "The evidence does not support a Finnish effect size for colorectal screening reminders, and the Finnish self-sampling gain over a reminder letter is about 3 points, far smaller than the international pooled estimate; no health effect is modelled for pathway timestamps."
}

